class Solution:
    def maximumXorProduct(self, a: int, b: int, n: int) -> int:
        MOD = 10**9 + 7
        if n == 0:
            return (a * b) % MOD

        # Fixed bits above position n-1 are unaffected by x
        current_a = a >> n
        current_b = b >> n

        for i in range(n - 1, -1, -1):
            a_i = (a >> i) & 1
            b_i = (b >> i) & 1

            if a_i == b_i:
                # Set x_i to make both (a XOR x) and (b XOR x) have 1 at this bit
                x_i = 1 - a_i
            else:
                # Give the 1 to whichever current value is larger (or equal)
                if current_a >= current_b:
                    x_i = a_i
                else:
                    x_i = b_i

            current_a = current_a * 2 + (a_i ^ x_i)
            current_b = current_b * 2 + (b_i ^ x_i)

        return (current_a * current_b) % MOD
